package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for DiscreteDistribution.getSamples().
 */
public class DiscreteDistribution_getSamples_TriageGen1Test {

    @Test
    public void testGetSamples_Success() {
        // Prepare input data
        List<Pair<Integer, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>(1, 0.2));
        inputSamples.add(new Pair<>(2, 0.3));
        inputSamples.add(new Pair<>(3, 0.5));

        // Initialize distribution
        DiscreteDistribution<Integer> distribution = new DiscreteDistribution<>(inputSamples);

        // Execute the method under test
        List<Pair<Integer, Double>> result = distribution.getSamples();

        // Verify results
        assertNotNull("The returned list should not be null", result);
        assertEquals("The size of the returned list should match the input size", inputSamples.size(), result.size());

        for (int i = 0; i < inputSamples.size(); i++) {
            Pair<Integer, Double> expected = inputSamples.get(i);
            Pair<Integer, Double> actual = result.get(i);

            assertEquals("Value at index " + i + " should match", expected.getFirst(), actual.getFirst());
            assertEquals("Probability at index " + i + " should match", expected.getSecond(), actual.getSecond(), 1e-10);
        }
    }




}

