import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for DiscreteDistribution.getSamples().
 */
public class DiscreteDistribution_getSamples_TriageGen1Test {





    @Test
    public void testGetSamples_SingleElement() {
        // Prepare single element input
        List<Pair<Double, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>(10.0, 1.0));

        // Initialize distribution
        DiscreteDistribution<Double> distribution = new DiscreteDistribution<>(inputSamples);

        // Execute
        List<Pair<Double, Double>> result = distribution.getSamples();

        // Verify
        assertEquals(1, result.size());
        assertEquals(10.0, result.get(0).getFirst(), 1e-10);
        assertEquals(1.0, result.get(0).getSecond(), 1e-10);
    }
}
